-- Read-only check for the notifier's new {RECIBE} (completion-notice-amount T1). Run on production.
-- Compares the current and the new subquery over the remittances completed in the last 30 days.
-- Expected: cambiados = only rows that had no amount, and every row that had an amount keeps the same text.
SELECT left(t.id::text, 8) AS op, t.service_type, 
  (SELECT CASE WHEN o.quoted_destination_amount IS NULL THEN NULL ELSE rtrim(rtrim(to_char(o.quoted_destination_amount, 'FM999,999,999,990.99'), '0'), '.') || ' ' || CASE (CASE WHEN lower(coalesce(o.delivery_method,'')) <> '' THEN lower(o.delivery_method) ELSE coalesce((SELECT b.beneficiary_type FROM remittance_beneficiaries b WHERE b.operation_id=o.id AND b.status='vigente' ORDER BY b.position LIMIT 1),'') END) WHEN 'zelle' THEN 'USD por Zelle' WHEN 'clasica' THEN 'USD de Clásica' WHEN 'tropical' THEN 'USD de Tropical' WHEN 'efectivo_usd' THEN 'USD en efectivo' WHEN 'cuban_card' THEN 'CUP' ELSE coalesce(o.destination_currency, '') END END FROM remittance_operations o WHERE o.id::text = t.id::text LIMIT 1) AS antes,
  (SELECT CASE WHEN x.monto IS NULL THEN NULL ELSE rtrim(rtrim(to_char(x.monto, 'FM999,999,999,990.99'), '0'), '.') || ' ' || CASE WHEN x.moneda = 'CUP' THEN 'CUP' ELSE CASE (CASE WHEN lower(coalesce(o.delivery_method,'')) <> '' THEN lower(o.delivery_method) ELSE coalesce((SELECT b.beneficiary_type FROM remittance_beneficiaries b WHERE b.operation_id=o.id AND b.status='vigente' ORDER BY b.position LIMIT 1),'') END) WHEN 'zelle' THEN 'USD por Zelle' WHEN 'clasica' THEN 'USD de Clásica' WHEN 'tropical' THEN 'USD de Tropical' WHEN 'efectivo_usd' THEN 'USD en efectivo' WHEN 'cuban_card' THEN (CASE WHEN x.moneda = 'USD' THEN 'USD' ELSE 'CUP' END) ELSE coalesce(x.moneda, o.destination_currency, '') END END END FROM remittance_operations o CROSS JOIN LATERAL (SELECT CASE WHEN o.quoted_destination_amount IS NOT NULL THEN o.quoted_destination_amount WHEN c.n = 1 THEN c.total WHEN bf.n = 1 AND bf.sin_monto = 0 AND bf.moneda IN ('USD','CUP') THEN bf.total END AS monto, CASE WHEN o.quoted_destination_amount IS NOT NULL THEN NULL WHEN c.n = 1 THEN c.moneda WHEN bf.n = 1 AND bf.sin_monto = 0 AND bf.moneda IN ('USD','CUP') THEN bf.moneda END AS moneda FROM (SELECT count(DISTINCT e.amount_currency) AS n, sum(e.amount) AS total, max(e.amount_currency) AS moneda FROM remittance_calculator_entries e WHERE e.operation_id = o.id AND e.voided_at IS NULL AND e.amount_currency IN ('USD','CUP')) c, (SELECT count(DISTINCT bb.currency) AS n, sum(bb.amount) AS total, max(bb.currency) AS moneda, count(*) FILTER (WHERE bb.amount IS NULL) AS sin_monto FROM remittance_beneficiaries bb WHERE bb.operation_id = o.id AND bb.status = 'vigente') bf) x WHERE o.id::text = t.id::text LIMIT 1) AS despues
FROM remittance_operations t WHERE t.status = 'completed' AND t.completed_at > now() - interval '30 days'
ORDER BY t.completed_at DESC
